const rawBody = $json.body ?? $json;
let body = rawBody;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (error) {
    throw new Error('Request body must be valid JSON');
  }
}

const payload = body && typeof body === 'object' && body.data && typeof body.data === 'object'
  ? body.data
  : body;
const ingredients = Array.isArray(payload?.ingredients) ? payload.ingredients : [];
const preferences = payload?.preferences ?? {};

if (ingredients.length === 0) {
  throw new Error('Missing ingredients array in request payload. Expected { ingredients: [...] }');
}

const normalizedPreferences = {
  portions: Number(preferences.portions ?? 1),
  cooks: Number(preferences.cooks ?? 1),
  cookingTime: String(preferences.cookingTime ?? 'medium'),
  cuisine: String(preferences.cuisine ?? 'fusion'),
  diets: Array.isArray(preferences.diets) ? preferences.diets : ['none'],
};

const ingredientSummary = ingredients
  .map((item) => `${item.quantity} ${item.unit} ${item.name}`.trim())
  .join(', ');

const prompt = `You are a culinary AI planner. Create exactly 3 recipe suggestions based on the provided data.

Ingredients: ${ingredientSummary}
Portions: ${normalizedPreferences.portions}
People cooking: ${normalizedPreferences.cooks}
Cooking time preference: ${normalizedPreferences.cookingTime}
Cuisine preference: ${normalizedPreferences.cuisine}
Diet preferences: ${normalizedPreferences.diets.join(', ')}

Output strict JSON with this schema:
{
  "recipes": [
    {
      "title": "string",
      "description": "string",
      "estimatedMinutes": number,
      "ingredients": ["string"],
      "steps": ["Step title: Step description"]
    }
  ]
}

Rules for steps:
- Return 4 to 8 steps per recipe.
- Each steps entry must be one string in the exact format "<short step title>: <clear instruction>".
- Keep titles short (2-6 words), action-oriented, and recipe-specific (example: "Cook the pasta").
- Never use generic labels like "Step" as the title.`;

return [{
  json: {
    ingredients,
    preferences: normalizedPreferences,
    prompt,
  },
}];

const agentOutput = $json.output ?? $json.text ?? $json;
const quotaData = $('Check IP Quota').first().json;
const requestData = $('Prepare Prompt').first().json;

const fallback = () => {
  const ingredients = Array.isArray(requestData?.ingredients) && requestData.ingredients.length ? requestData.ingredients : ['tomato', 'garlic', 'olive oil'];
  const cuisine = requestData?.preferences?.cuisine || 'fusion';
  return [1, 2, 3].map((number) => ({
    title: `${cuisine} recipe ${number}`,
    description: 'A simple recipe based on your ingredients.',
    estimatedMinutes: 30,
    ingredients: ingredients.slice(0, 7),
    steps: ['Prepare ingredients: wash and chop everything.', 'Cook aromatics: heat oil and add the aromatics.', 'Combine ingredients: add the remaining ingredients.', 'Season and finish: cook until tender and serve.']
  }));
};

let result = agentOutput;
if (typeof result === 'string') {
  const cleaned = result.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  try {
    result = JSON.parse(cleaned);
  } catch (error) {
    result = { recipes: fallback() };
  }
}

const recipes = result && typeof result === 'object' && Array.isArray(result.recipes) ? result.recipes : [];
const valid = recipes.length === 3 && recipes.every((recipe) => recipe && typeof recipe.title === 'string' && typeof recipe.description === 'string' && Number.isFinite(Number(recipe.estimatedMinutes)) && Array.isArray(recipe.ingredients) && recipe.ingredients.length > 0 && Array.isArray(recipe.steps) && recipe.steps.length >= 4 && recipe.steps.length <= 8 && recipe.steps.every((step) => typeof step === 'string' && step.includes(':')));

return [{ json: { ...quotaData, ingredients: requestData.ingredients, preferences: requestData.preferences, recipeResult: { recipes: valid ? recipes : fallback() }, recipeError: false, recipeErrorMessage: null } }];

const webhookInput = $('Recipe Webhook').first().json;
const rawBody = webhookInput.body ?? webhookInput;
const body = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
const payload = body?.data && typeof body.data === 'object' ? body.data : body;

return [{
  json: {
    ...$json,
    ingredients: Array.isArray(payload?.ingredients) ? payload.ingredients : [],
    preferences: payload?.preferences ?? {},
  },
}];

