const body = $json.body ?? $json;

let ip = String(body.clientIp || '').trim();

if (!ip || ip === '127.0.0.1') {
  try {
    const ipResponse = await fetch('https://api.ipify.org?format=json');
    if (ipResponse.ok) {
      const ipData = await ipResponse.json();
      ip = ipData.ip || '127.0.0.1';
    }
  } catch (error) {
    ip = '127.0.0.1';
  }
}

const ipSlug = ip.replace(/[^a-zA-Z0-9]/g, '-').replace(/^-+|-+$/g, '') || 'localhost';
const now = Date.now();
const windowMs = 24 * 60 * 60 * 1000;
const cutoff = now - windowMs;
const today = new Date(now).toISOString().slice(0, 10);
const dbUrl = 'https://code-a-cuisine-ccf1f-default-rtdb.firebaseio.com';
const perIpPath = `${dbUrl}/quotaRolling/ips/${ipSlug}.json`;
const globalPath = `${dbUrl}/quota/${today}/global.json`;
const perIpLimit = 50;
const globalLimit = 50;

const staticData = $getWorkflowStaticData('global');
if (!staticData.quotaRollingIps || typeof staticData.quotaRollingIps !== 'object') {
  staticData.quotaRollingIps = {};
}
if (!staticData.quotaGlobalDaily || typeof staticData.quotaGlobalDaily !== 'object') {
  staticData.quotaGlobalDaily = {};
}

const normalizeRecentTimestamps = (value, minTimestamp) => {
  const source = Array.isArray(value) ? value : [];
  return source
    .map((entry) => Number(entry))
    .filter((entry) => Number.isFinite(entry) && entry >= minTimestamp)
    .sort((a, b) => a - b);
};

const extractRecentTimestamps = (value, minTimestamp) => {
  let rawTimestamps = [];

  if (Array.isArray(value)) {
    rawTimestamps = value;
  } else if (value && typeof value === 'object' && Array.isArray(value.timestamps)) {
    rawTimestamps = value.timestamps;
  }

  return rawTimestamps
    .map((entry) => Number(entry))
    .filter((entry) => Number.isFinite(entry) && entry >= minTimestamp)
    .sort((a, b) => a - b);
};

const readCounter = (value) => {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return Math.max(0, value);
  }

  if (value && typeof value === 'object') {
    const possibleCount = value.count ?? value.used ?? value.perIpUsed ?? value.globalUsed;
    if (typeof possibleCount === 'number' && Number.isFinite(possibleCount)) {
      return Math.max(0, possibleCount);
    }
  }

  return 0;
};

const readJson = async (path) => {
  try {
    const response = await fetch(path);
    if (!response.ok) {
      let details = '';
      try {
        details = await response.text();
      } catch (error) {
        details = '';
      }

      return {
        success: false,
        data: null,
        error: `Read failed (${response.status} ${response.statusText}) ${details}`.trim(),
      };
    }

    return {
      success: true,
      data: await response.json(),
      error: null,
    };
  } catch (error) {
    return {
      success: false,
      data: null,
      error: error.message,
    };
  }
};

const writeJson = async (path, value) => {
  const response = await fetch(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(value),
  });

  if (!response.ok) {
    let details = '';
    try {
      details = await response.text();
    } catch (error) {
      details = '';
    }

    throw new Error(`Write failed (${response.status} ${response.statusText}) ${details}`.trim());
  }
};

const localPerIpTimestamps = normalizeRecentTimestamps(staticData.quotaRollingIps[ipSlug], cutoff);
staticData.quotaRollingIps[ipSlug] = localPerIpTimestamps;
const localGlobalUsed = Math.max(0, Number(staticData.quotaGlobalDaily[today] ?? 0));

const [remotePerIpResult, remoteGlobalResult] = await Promise.all([
  readJson(perIpPath),
  readJson(globalPath),
]);

const remotePerIpTimestamps = remotePerIpResult.success
  ? extractRecentTimestamps(remotePerIpResult.data, cutoff)
  : null;
const remoteGlobalUsed = remoteGlobalResult.success
  ? readCounter(remoteGlobalResult.data)
  : null;

const perIpTimestamps = remotePerIpTimestamps ?? localPerIpTimestamps;
const perIpUsed = perIpTimestamps.length;
const globalUsed = Number.isFinite(remoteGlobalUsed) ? remoteGlobalUsed : localGlobalUsed;

const quota = {
  date: new Date(now).toISOString(),
  ipAddress: ip,
  ipVersion: 'unknown',
  windowHours: 24,
  perIpLimit,
  perIpUsed,
  perIpRemaining: Math.max(0, perIpLimit - perIpUsed),
  globalLimit,
  globalUsed,
  globalRemaining: Math.max(0, globalLimit - globalUsed),
};

let quotaOk = quota.perIpRemaining > 0 && quota.globalRemaining > 0;
let quotaExceededMessage = null;
let quotaWriteOk = true;
let quotaWarning = null;

if (!quotaOk) {
  quotaExceededMessage = quota.perIpRemaining <= 0
    ? `Generation limit reached. You can generate up to ${perIpLimit} recipes within 24 hours from this IP address.`
    : `System-wide daily generation limit reached. Up to ${globalLimit} recipes can be generated across the app per day.`;
} else {
  const nextPerIpTimestamps = [...perIpTimestamps, now];
  const nextGlobalUsed = globalUsed + 1;

  staticData.quotaRollingIps[ipSlug] = nextPerIpTimestamps;
  staticData.quotaGlobalDaily[today] = nextGlobalUsed;

  const writeErrors = [];

  try {
    await writeJson(perIpPath, { timestamps: nextPerIpTimestamps, updatedAt: new Date(now).toISOString() });
  } catch (error) {
    writeErrors.push(`per-ip write: ${error.message}`);
  }

  try {
    await writeJson(globalPath, nextGlobalUsed);
  } catch (error) {
    writeErrors.push(`global write: ${error.message}`);
  }

  quota.perIpUsed = nextPerIpTimestamps.length;
  quota.perIpRemaining = Math.max(0, perIpLimit - nextPerIpTimestamps.length);
  quota.globalUsed = nextGlobalUsed;
  quota.globalRemaining = Math.max(0, globalLimit - nextGlobalUsed);

  if (writeErrors.length > 0) {
    quotaWriteOk = false;
    quotaWarning = `Firebase sync failed, local fallback is active: ${writeErrors.join(' | ')}`;
    console.log(quotaWarning);
  }
}

return [{
  json: {
    ...$json,
    ipAddress: ip,
    ipSlug,
    quotaDate: today,
    quotaOk,
    quotaWriteOk,
    quotaWarning,
    quota,
    quotaExceededMessage,
  },
}];
